{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles Just Cause for Eviction Ordinance (JCO)","requirement":"A landlord may not terminate a tenancy without just cause and must pay relocation assistance for no-fault evictions (owner move-in, demolition, government order, affordable-housing conversion); non-payment evictions require rent owed above Fair Market Rent.","key_value":null,"coverage_conditions":"Most City of Los Angeles residential rentals not regulated by the RSO and not otherwise excepted; applies once a tenant has lived in the unit six months or the original lease expired.","applicability":{"conditions":[{"type":"other","role":"exempt","text":"Units regulated by the City's Rent Stabilization Ordinance are not covered"},{"type":"owner","role":"exempt","who":"HACLA or government-owned","unit_limit":null}],"per_tenancy":"Covered only where the tenant has lived in the unit at least six months or the original lease has expired, whichever comes first.","coverage_quotes":["The JCO covers most residential properties in the City of Los Angeles that are not regulated by the City’s Rent Stabilization Ordinance (RSO).","In order to apply to a tenancy, it requires that the tenant either has lived in the same unit for at least six months or that their original lease expired, whichever comes first."]},"exemptions":"Transient hotels; licensed care facilities; fraternity or sorority houses; owner's roommate; some cooperatives; some non-profit homeless facilities and short-term substance-abuse treatment centers; some properties owned by HACLA or the government.","penalty":null,"effective_date":null,"valid_through":null,"citation":"Los Angeles Just Cause Ordinance (L.A.M.C. §165.00 et seq.)","quoted_span":"It prohibits terminations of tenancies without just cause and requires relocation assistance for no-fault evictions.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"CA","category":"rent_increase_limits","lifecycle":"enacted","title":"California Tenant Protection Act (AB 1482) annual rent cap","requirement":"For covered units older than 15 years, annual rent increases are capped at 5% plus the regional cost-of-living change, or 10%, whichever is lower; for Aug 1, 2024 to Jul 31, 2025 the maximum allowable increase is 8.9%.","key_value":"5% + CPI or 10%, whichever is lower; 8.9% for Aug 1, 2024–Jul 31, 2025","coverage_conditions":"Units older than 15 years, excluding units built in the last 15 years, deed-restricted affordable units, dormitories, owner-occupied two-unit properties, qualifying single-family homes and condos, and RSO units.","applicability":{"conditions":[{"type":"built_within_years","role":"exempt","years":15,"basis":"construction"},{"type":"other","role":"exempt","text":"Units restricted by a deed or recorded document limiting affordability to low- or moderate-income households are not covered"},{"type":"owner","role":"exempt","who":"owner-occupied two-unit property","unit_limit":2},{"type":"owner","role":"exempt","who":"single-family homes and condominiums not owned by a real estate trust, corporation or LLC with a corporate member","unit_limit":null},{"type":"other","role":"exempt","text":"Units already subject to the City's Rent Stabilization Ordinance are not covered"}],"per_tenancy":null,"coverage_quotes":["may regulate the rent amount in buildings that are older than 15 years old.","Units that were constructed within the last 15 years","A two-unit property, provided the second unit was occupied by an owner of the property for the entire period of the tenancy."]},"exemptions":"Units constructed within the last 15 years; deed-restricted affordable units; certain dormitories; owner-occupied two-unit properties; qualifying single-family homes and condominiums; units already subject to the City's RSO.","penalty":null,"effective_date":null,"valid_through":null,"citation":"Cal. Civ. Code § 1947.12","quoted_span":"Effective August 1, 2024 to July 31, 2025, the maximum allowable increase is 8.9%.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D040-01","n_rules":2,"note":null}

